class KeyValuePairCB(Callback):
    "Add a single key-value pair as a NetCDF global attribute."
    def __init__(self, 
                 k, # NetCDF global attribute key name
                 v  # NetCDF global attribute value
                ): store_attr()
    def __call__(self, obj): obj.attrs[self.k] = self.v
